1	import path from 'path';
2	import { writeFile } from './files';
3	import { PageData } from './page';
4	import { getEngine, loadTemplate, loadLayout, loadPartials } from './template';
5	
6	export async function generatePageHtml(page: PageData, outputDir: string, templateDir?: string): Promise<void> {
7	  let html: string;
8	
9	  if (templateDir) {
10	    html = await createPageHtmlWithTemplate(page, templateDir);
11	  } else {
12	    html = createPageHtml(page);
13	  }
14	
15	  const filePath = path.join(outputDir, `${page.slug}.html`);
16	  await writeFile(filePath, html);
17	}
18	
19	export async function generateIndexHtml(pages: PageData[], outputDir: string): Promise<void> {
20	  const html = createIndexHtml(pages);
21	  const filePath = path.join(outputDir, 'index.html');
22	  await writeFile(filePath, html);
23	}
24	
25	async function createPageHtmlWithTemplate(page: PageData, templateDir: string): Promise<string> {
26	  await loadPartials(templateDir);
27	  const eng = getEngine();
28	
29	  let html = page.html;
30	
31	  // Apply template if specified
32	  if (page.template) {
33	    const templateContent = await loadTemplate(page.template, templateDir);
34	    html = eng.render(templateContent, { ...page, body: page.html });
35	  }
36	
37	  // Apply layout if specified
38	  if (page.layout) {
39	    const layout = await loadLayout(page.layout, templateDir);
40	    html = eng.render(layout, { ...page, body: html });
41	  }
42	
43	  return html;
44	}
