46	function createPageHtml(page: PageData): string {
47	  const tagsList = page.tags && Array.isArray(page.tags)
48	    ? `<div class="tags">${page.tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}</div>`
49	    : '';
50	
51	  const dateHtml = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';
52	
53	  return `<!DOCTYPE html>
54	<html lang="en">
55	<head>
56	  <meta charset="UTF-8">
57	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
58	  <title>${escapeHtml(page.title)}</title>
59	  <style>
60	    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; color: #333; }
61	    h1 { color: #000; margin-bottom: 10px; }
62	    .meta { color: #666; margin-bottom: 20px; border-bottom: 1px solid #eee; padding-bottom: 10px; }
63	    .date { margin: 0; font-size: 0.9em; }
64	    .tags { margin-top: 10px; }
65	    .tag { display: inline-block; background: #f0f0f0; padding: 4px 8px; margin-right: 5px; border-radius: 3px; font-size: 0.85em; }
66	    .content { margin-top: 20px; }
67	    a { color: #0066cc; }
68	    code { background: #f5f5f5; padding: 2px 4px; border-radius: 3px; }
69	    pre { background: #f5f5f5; padding: 10px; border-radius: 3px; overflow-x: auto; }
70	    .back-link { margin-top: 30px; padding-top: 20px; border-top: 1px solid #eee; }
71	  </style>
72	</head>
73	<body>
74	  <article>
75	    <h1>${escapeHtml(page.title)}</h1>
76	    <div class="meta">
77	      ${dateHtml}
78	      ${tagsList}
79	    </div>
80	    <div class="content">
81	      ${page.html}
82	    </div>
83	  </article>
84	  <footer class="back-link">
85	    <a href="index.html">← Back to all pages</a>
86	  </footer>
87	</body>
88	</html>`;
89	}
90	
91	function createIndexHtml(pages: PageData[]): string {
92	  const pagesList = pages
93	    .sort((a, b) => {
94	      if (!a.date || !b.date) return 0;
95	      return new Date(b.date).getTime() - new Date(a.date).getTime();
96	    })
97	    .map(page => `
98	    <li>
99	      <a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>
100	      ${page.date ? `<span class="date"> — ${escapeHtml(page.date)}</span>` : ''}
101	      ${page.tags && Array.isArray(page.tags) ? `<div class="tags">${page.tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}</div>` : ''}
102	    </li>
103	  `).join('');
104	
105	  return `<!DOCTYPE html>
106	<html lang="en">
107	<head>
108	  <meta charset="UTF-8">
109	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
110	  <title>All Pages</title>
111	  <style>
112	    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; color: #333; }
113	    h1 { color: #000; }
114	    ul { list-style: none; padding: 0; }
115	    li { padding: 10px 0; border-bottom: 1px solid #eee; }
116	    li:last-child { border-bottom: none; }
117	    a { color: #0066cc; text-decoration: none; font-weight: 500; }
118	    a:hover { text-decoration: underline; }
119	    .date { color: #666; font-size: 0.9em; margin-left: 10px; }
120	    .tags { margin-top: 5px; display: flex; flex-wrap: wrap; gap: 5px; }
121	    .tag { display: inline-block; background: #f0f0f0; padding: 4px 8px; border-radius: 3px; font-size: 0.85em; color: #666; }
122	  </style>
123	</head>
124	<body>
125	  <h1>All Pages</h1>
126	  <p>Total: ${pages.length} page${pages.length === 1 ? '' : 's'}</p>
127	  <ul>
128	    ${pagesList}
129	  </ul>
130	</body>
131	</html>`;
132	}
133	
134	function escapeHtml(text: string): string {
135	  const map: { [key: string]: string } = {
136	    '&': '&amp;',
137	    '<': '&lt;',
138	    '>': '&gt;',
139	    '"': '&quot;',
140	    "'": '&#039;'
141	  };
142	  return text.replace(/[&<>"']/g, char => map[char]);
143	}
