21	
22	  const pages = [];
23	  for (const file of files) {
24	    const page = await processMarkdownFile(file.name, file.content);
25	    pages.push(page);
26	    await generatePageHtml(page, outputDir, templateDir);
27	    console.log(`✓ Generated ${page.slug}.html`);
