77	      return yargs
78	        .option('content', {
79	          alias: 'c',
80	          describe: 'Content directory',
81	          type: 'string',
82	          default: './content'
83	        })
84	        .option('output', {
85	          alias: 'o',
86	          describe: 'Output directory',
