1	import Handlebars from 'handlebars';
2	import { promises as fs } from 'fs';
3	import path from 'path';
4	
5	export interface TemplateEngine {
6	  registerPartial(name: string, content: string): void;
7	  render(templateContent: string, data: Record<string, unknown>): string;
8	}
9	
10	let defaultTemplateDir = './templates';
11	let defaultLayoutName = 'default';
12	let engine: TemplateEngine | null = null;
13	
14	export function setTemplateDir(dir: string): void {
15	  defaultTemplateDir = dir;
16	}
17	
18	export function setDefaultLayout(name: string): void {
19	  defaultLayoutName = name;
20	}
21	
22	export function createTemplateEngine(): TemplateEngine {
23	  return {
24	    registerPartial(name: string, content: string): void {
25	      Handlebars.registerPartial(name, content);
26	    },
27	    render(templateContent: string, data: Record<string, unknown>): string {
28	      const template = Handlebars.compile(templateContent);
29	      return template(data);
30	    }
31	  };
32	}
33	
34	export function getEngine(): TemplateEngine {
35	  if (!engine) {
36	    engine = createTemplateEngine();
37	  }
38	  return engine;
39	}
40	
41	export async function loadPartials(templateDir: string): Promise<void> {
42	  const partialsDir = path.join(templateDir, 'partials');
43	  const eng = getEngine();
44	
45	  try {
46	    const files = await fs.readdir(partialsDir);
47	    for (const file of files) {
48	      if (file.endsWith('.hbs')) {
49	        const filePath = path.join(partialsDir, file);
50	        const content = await fs.readFile(filePath, 'utf-8');
51	        const partialName = file.replace(/\.hbs$/, '');
52	        eng.registerPartial(partialName, content);
53	      }
54	    }
55	  } catch (error) {
56	    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
57	      throw error;
58	    }
59	  }
60	}
61	
62	export async function loadTemplate(templateName: string, templateDir: string): Promise<string> {
63	  const templatePath = path.join(templateDir, `${templateName}.hbs`);
64	  try {
65	    return await fs.readFile(templatePath, 'utf-8');
66	  } catch (error) {
67	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
68	      // Try loading from layouts directory
69	      const layoutPath = path.join(templateDir, 'layouts', `${templateName}.hbs`);
70	      return await fs.readFile(layoutPath, 'utf-8');
71	    }
72	    throw error;
73	  }
74	}
75	
76	export async function loadLayout(layoutName: string, templateDir: string): Promise<string> {
77	  const layoutPath = path.join(templateDir, 'layouts', `${layoutName}.hbs`);
78	  try {
79	    return await fs.readFile(layoutPath, 'utf-8');
80	  } catch (error) {
81	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
82	      // Return a default layout if the specified one doesn't exist
83	      return '{{body}}';
84	    }
85	    throw error;
86	  }
87	}
88	
89	export async function renderPage(
90	  pageHtml: string,
91	  templateContent: string | null,
92	  layoutName: string | null,
93	  pageData: Record<string, unknown>,
94	  templateDir: string
95	): Promise<string> {
96	  const eng = getEngine();
97	
98	  // Step 1: If a template is specified, render the page with the template
99	  let html = pageHtml;
100	  if (templateContent) {
101	    html = eng.render(templateContent, { ...pageData, body: pageHtml });
102	  }
103	
104	  // Step 2: If a layout is specified, wrap with layout
105	  if (layoutName) {
106	    const layout = await loadLayout(layoutName, templateDir);
107	    html = eng.render(layout, { ...pageData, body: html });
108	  }
109	
110	  return html;
111	}
