1	import express, { Express, Request, Response } from 'express';
2	import path from 'path';
3	import { WebSocketServer, WebSocket } from 'ws';
4	import { createServer, Server as HttpServer } from 'http';
5	import chokidar, { FSWatcher } from 'chokidar';
6	import { promises as fs } from 'fs';
7	import { readMarkdownFiles } from './files';
8	import { processMarkdownFile } from './page';
9	import { generatePageHtml, generateIndexHtml } from './generator';
10	
11	let clients: WebSocket[] = [];
12	
13	function broadcastReload(): void {
14	  const message = JSON.stringify({ type: 'reload' });
15	  clients = clients.filter(client => client.readyState === WebSocket.OPEN);
16	  clients.forEach(client => {
17	    client.send(message);
18	  });
19	}
20	
21	function injectReloadScript(html: string): string {
22	  const script = `<script>
23	(function() {
24	  const ws = new WebSocket('ws://' + window.location.host);
25	  ws.onmessage = (event) => {
26	    const data = JSON.parse(event.data);
27	    if (data.type === 'reload') {
28	      window.location.reload();
29	    }
30	  };
31	  ws.onerror = () => {
32	    setTimeout(() => {
33	      window.location.reload();
34	    }, 1000);
35	  };
36	})();
37	</script>`;
38	
39	  if (html.includes('</body>')) {
40	    return html.replace('</body>', script + '\n</body>');
41	  }
42	  return html + script;
43	}
44	
45	async function serveFile(filePath: string, distDir: string): Promise<string> {
46	  try {
47	    let content = await fs.readFile(filePath, 'utf-8');
48	
49	    if (filePath.endsWith('.html')) {
50	      content = injectReloadScript(content);
51	    }
52	
53	    return content;
54	  } catch (error) {
55	    throw error;
56	  }
57	}
58	
59	async function rebuild(
60	  contentDir: string,
61	  distDir: string,
62	  templateDir: string | undefined
63	): Promise<void> {
64	  try {
65	    console.log('Rebuilding...');
66	    const files = await readMarkdownFiles(contentDir);
67	
68	    if (files.length === 0) {
69	      console.log('No markdown files found.');
70	      return;
71	    }
72	
73	    const pages = [];
74	    for (const file of files) {
75	      const page = await processMarkdownFile(file.name, file.content);
76	      pages.push(page);
77	      await generatePageHtml(page, distDir, templateDir);
78	    }
79	
80	    await generateIndexHtml(pages, distDir);
81	    console.log('Build complete, reloading browser...');
82	    broadcastReload();
83	  } catch (error) {
84	    console.error('Rebuild error:', (error as Error).message);
85	  }
86	}
87	
88	export async function serve(
89	  distDir: string,
90	  contentDir: string,
91	  templateDir: string | undefined,
92	  port: number = 3000
93	): Promise<void> {
94	  const app: Express = express();
95	  const server: HttpServer = createServer(app);
96	  const wss = new WebSocketServer({ server });
97	
98	  wss.on('connection', (ws: WebSocket) => {
99	    clients.push(ws);
100	  });
101	
102	  app.use(express.static(distDir));
103	
104	  app.get('*', async (req: Request, res: Response) => {
105	    let requestPath = req.path === '/' ? '/index.html' : req.path;
106	
107	    if (!requestPath.endsWith('.html')) {
108	      requestPath += '.html';
109	    }
110	
111	    const filePath = path.join(distDir, requestPath);
112	
113	    try {
114	      const content = await serveFile(filePath, distDir);
115	      res.type('text/html').send(content);
116	    } catch (error) {
117	      res.status(404).type('text/html').send(
118	        injectReloadScript(`<!DOCTYPE html>
119	<html>
120	<head><title>404 Not Found</title></head>
121	<body><h1>404 - Page not found</h1></body>
122	</html>`)
123	      );
124	    }
125	  });
126	
127	  server.listen(port, () => {
128	    console.log(`Dev server running at http://localhost:${port}`);
129	  });
130	
131	  const watchDirs: string[] = [contentDir];
132	  if (templateDir) {
133	    watchDirs.push(templateDir);
134	  }
135	
136	  const watcher: FSWatcher = chokidar.watch(watchDirs, {
137	    ignored: /node_modules/,
138	    persistent: true
139	  });
140	
141	  let rebuildTimeout: NodeJS.Timeout;
142	
