import { PageData } from './page';

export interface PluginContext {
  contentDir: string;
  outputDir: string;
  templateDir?: string;
}

export interface Plugin {
  name: string;
  onStart?: (context: PluginContext) => Promise<void>;
  beforeBuild?: (context: PluginContext) => Promise<void>;
  onFile?: (page: PageData, context: PluginContext) => Promise<PageData>;
  afterBuild?: (pages: PageData[], context: PluginContext) => Promise<void>;
  onEnd?: (context: PluginContext) => Promise<void>;
}

export class PluginManager {
  private plugins: Plugin[] = [];

  register(plugin: Plugin): void {
    this.plugins.push(plugin);
  }

  async executeHook(
    hookName: keyof Plugin,
    context: PluginContext,
    ...args: unknown[]
  ): Promise<unknown> {
    let result: unknown = args[0];

    for (const plugin of this.plugins) {
      const hook = plugin[hookName];
      if (hook && typeof hook === 'function') {
        result = await hook.call(plugin, result, context);
      }
    }

    return result;
  }

  async runOnStart(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onStart) {
        await plugin.onStart(context);
      }
    }
  }

  async runBeforeBuild(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.beforeBuild) {
        await plugin.beforeBuild(context);
      }
    }
  }

  async runOnFile(page: PageData, context: PluginContext): Promise<PageData> {
    let result = page;

    for (const plugin of this.plugins) {
      if (plugin.onFile) {
        result = await plugin.onFile(result, context);
      }
    }

    return result;
  }

  async runAfterBuild(pages: PageData[], context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.afterBuild) {
        await plugin.afterBuild(pages, context);
      }
    }
  }

  async runOnEnd(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onEnd) {
        await plugin.onEnd(context);
      }
    }
  }
}

import { Plugin, PluginContext } from '../plugin';
import { PageData } from '../page';
import { markdownToHtml } from '../markdown';

export const MarkdownPlugin: Plugin = {
  name: 'markdown',

  onFile: async (page: PageData, _context: PluginContext): Promise<PageData> => {
    return page;
  }
};

import { Plugin, PluginContext } from '../plugin';
import { PageData } from '../page';
import { loadPartials, loadTemplate, loadLayout, getEngine } from '../template';

export const TemplatePlugin: Plugin = {
  name: 'template',

  beforeBuild: async (context: PluginContext): Promise<void> => {
    if (context.templateDir) {
      await loadPartials(context.templateDir);
    }
  },

  onFile: async (page: PageData, context: PluginContext): Promise<PageData> => {
    if (!context.templateDir) {
      return page;
    }

    const eng = getEngine();
    let html = page.html;

    if (page.template) {
      const templateContent = await loadTemplate(page.template, context.templateDir);
      html = eng.render(templateContent, { ...page, body: page.html });
    }

    if (page.layout) {
      const layout = await loadLayout(page.layout, context.templateDir);
      html = eng.render(layout, { ...page, body: html });
    }

    return {
      ...page,
      html
    };
  }
};

import { Plugin, PluginContext } from '../plugin';
import { PageData } from '../page';
import express, { Express, Request, Response } from 'express';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import { createServer, Server as HttpServer } from 'http';
import chokidar, { FSWatcher } from 'chokidar';
import { promises as fs } from 'fs';

interface DevServerConfig {
  port: number;
  onRebuild?: () => Promise<void>;
}

let devServerConfig: DevServerConfig | null = null;
let clients: WebSocket[] = [];
let server: HttpServer | null = null;
let watcher: FSWatcher | null = null;

function broadcastReload(): void {
  const message = JSON.stringify({ type: 'reload' });
  clients = clients.filter(client => client.readyState === WebSocket.OPEN);
  clients.forEach(client => {
    client.send(message);
  });
}

function injectReloadScript(html: string): string {
  const script = `<script>
(function() {
  const ws = new WebSocket('ws://' + window.location.host);
  ws.onmessage = (event) => {
    const data = JSON.parse(event.data);
    if (data.type === 'reload') {
      window.location.reload();
    }
  };
  ws.onerror = () => {
    setTimeout(() => {
      window.location.reload();
    }, 1000);
  };
})();
</script>`;

  if (html.includes('</body>')) {
    return html.replace('</body>', script + '\n</body>');
  }
  return html + script;
}

async function serveFile(filePath: string): Promise<string> {
  try {
    let content = await fs.readFile(filePath, 'utf-8');

    if (filePath.endsWith('.html')) {
      content = injectReloadScript(content);
    }

    return content;
  } catch (error) {
    throw error;
  }
}

export function createDevServerPlugin(config: DevServerConfig): Plugin {
  return {
    name: 'dev-server',

    onStart: async (context: PluginContext): Promise<void> => {
      devServerConfig = config;

      const app: Express = express();
      server = createServer(app);
      const wss = new WebSocketServer({ server });

      wss.on('connection', (ws: WebSocket) => {
        clients.push(ws);
      });

      app.use(express.static(context.outputDir));

      app.get('*', async (req: Request, res: Response) => {
        let requestPath = req.path === '/' ? '/index.html' : req.path;

        if (!requestPath.endsWith('.html')) {
          requestPath += '.html';
        }

        const filePath = path.join(context.outputDir, requestPath);

        try {
          const content = await serveFile(filePath);
          res.type('text/html').send(content);
        } catch (error) {
          res.status(404).type('text/html').send(
            injectReloadScript(`<!DOCTYPE html>
<html>
<head><title>404 Not Found</title></head>
<body><h1>404 - Page not found</h1></body>
</html>`)
          );
        }
      });

      server.listen(config.port, () => {
        console.log(`Dev server running at http://localhost:${config.port}`);
      });

      const watchDirs: string[] = [context.contentDir];
      if (context.templateDir) {
        watchDirs.push(context.templateDir);
      }

      watcher = chokidar.watch(watchDirs, {
        ignored: /node_modules/,
        persistent: true
      });

      let rebuildTimeout: NodeJS.Timeout;

      watcher.on('change', () => {
        clearTimeout(rebuildTimeout);
        rebuildTimeout = setTimeout(async () => {
          if (config.onRebuild) {
            await config.onRebuild();
          }
          console.log('Build complete, reloading browser...');
          broadcastReload();
        }, 300);
      });
    },

    onEnd: async (_context: PluginContext): Promise<void> => {
      if (watcher) {
        await watcher.close();
      }
      if (server) {
        server.close();
      }
    },

    onFile: async (page: PageData, _context: PluginContext): Promise<PageData> => {
      return page;
    }
  };
}

