export async function generatePageHtml(
  page: PageData,
  outputDir: string,
  templateDir?: string,
  pluginManager?: PluginManager
): Promise<void> {
  let html: string;

  if (pluginManager) {
    const context: PluginContext = { contentDir: '', outputDir, templateDir };
    const processedPage = await pluginManager.runOnFile(page, context);
    html = processedPage.html;
  } else if (templateDir) {
    html = await createPageHtmlWithTemplate(page, templateDir);
  } else {
    html = createPageHtml(page);
  }

  const filePath = path.join(outputDir, `${page.slug}.html`);
  await writeFile(filePath, html);
}

export async function generateIndexHtml(pages: PageData[], outputDir: string): Promise<void> {
  const html = createIndexHtml(pages);
  const filePath = path.join(outputDir, 'index.html');
  await writeFile(filePath, html);
}

async function createPageHtmlWithTemplate(page: PageData, templateDir: string): Promise<string> {
  const { loadPartials, getEngine, loadTemplate, loadLayout } = await import('./template');
  await loadPartials(templateDir);
  const eng = getEngine();

  let html = page.html;

  if (page.template) {
    const templateContent = await loadTemplate(page.template, templateDir);
    html = eng.render(templateContent, { ...page, body: page.html });
  }

  if (page.layout) {
    const layout = await loadLayout(page.layout, templateDir);
    html = eng.render(layout, { ...page, body: html });
  }

  return html;
}

